import bisect

def difficulty(n, seq, queries):
    prev_count = {val: 1 for val in set(seq)}
    nxt_count = {val: 0 for val in set(seq)}

    for i, val in enumerate(seq):
        prev_count[val] += 1
        nxt_count[val + 1] += 1
        nxt_count[val - 1] -= 1

    changes = 0
    for count in nxt_count.values():
        changes += len(seq) - bisect.bisect_left(nxt_count, 0) - (prev_count[count] > 0)

    prev_seq = list(seq)
    nxt_seq = [0] * n
    for i, val in enumerate(seq):
        nxt_seq[prev_seq.index(val)] += val
        prev_seq[prev_seq.index(val)] = val

    seqs = [prev_seq, nxt_seq]
    for query in queries:
        i, src = query
        idx = bisect.bisect_left(seq, i)
        if idx == len(seq):
            dst = src
        else:
            dst = prev_seq[idx]
        nseq = seqs[idx]
        for val in range(nseq[idx], -1, -1):
            nxt_seq[bisect.bisect_left(seq, i) - 1] -= val

        nseq = seqs[idx]
        for val in range(nseq[idx], seq[idx], 1):
            seqs.insert(0, nseq)
            nseq = seqs.pop()

        seqs[0][idx] = src
        seqs[-1][prev_seq.index(src)] += 1

        seq = seqs[1] if idx < n - 1 else seqs[0]
        for pos in range(idx, n - 1):
            x = seq[pos]
            if prev_seq[pos] != x:
                seq[pos] = 0
            if idx > 0 and seq[pos - 1] == x:
                seq[pos - 1] = 0
        if seq[idx] != 0:
            seq[pos] = 0
            pos -= 1
        while idx >= 0 and seq[idx] == 0:
            idx -= 1
        while pos + 1 < n and seq[pos + 1] == 0:
            pos += 1

        for i in range(len(prev_seq)):
            if prev_seq[i] == i:
                break
        if i == len(prev_seq) - 1:
            return seq

