class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.cont = n
        self.priority = n

    def find(self, u):
        if u != self.parent[u]:
            self.parent[u] = self.find(self.parent[u])
        return self.parent[u]

