from collections import deque

def create_tournament(scores):
    n = len(scores)
    graph = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if scores[i] < scores[j]:
                graph[i][j] = 1
                graph[j][i] = 0
            else:
                graph[i][j] = 0
                graph[j][i] = 1
    return graph

def verify_tournament(scores, n):
    d1 = max(scores)
    d2 = scores[1]
    graph = create_tournament(scores)
    for i in range(n):
        for j in range(n):
            if graph[i][j] == 1:
                if d1 < d2:
                    return False, 0
                d2 = d1 - d2
                d1 = max([d1]) if d1 > d2 else d2
    if d1 != scores[-1]:
        return False, 0
    return True, d1

def find_tournament(s):
    m = len(s)
    graph_exists = False
    vertices = []
    buf = deque([])
    buf.extend(s)
    targets = {i: 0 for i in range(m)}
    while buf:
        v = buf.popleft()
        vertices.append(v)
        for i in range(m):
            if graph_exists or i not in targets:
                continue
            to_check = s.copy()
            if i not in to_check:
                to_check.pop(i)
            if len(to_check) == 0:
                graph_exists = True
                continue
            max_b, max_score = 0, 0
            to_check.sort()
            if level := find_tournament(to_check[:]):
                vertices.sort()
                target = targets[i]
                graphs, max_b = level[0], -1
                for graph in graphs:
                    possible, score = verify_tournament(graph, i)
                    if possible:
                        if score != max_score:
                            continue
                        max_score = score
                        targets[target] = i
                        buf.extend([i] + graph)
                        break
                    if score > max_score:
                        max_b = level[0]
                        max_score = score
                        targets[target] = i
                vertices.extend(range(max_b, max_score + targets[tuple(sorted(vertices))]))
                break
            else:
                continue
    n = len(vertices)
    tournament = [[0]*n for _ in range(n)]
    if not graph_exists:
        return "=("
    for vertex in vertices:
        for target in targets[vertex]:
            tournament[targets[vertex]][vertex] = 1
    return n, '\n'.join(['\t'.join([str(x) for x in row]) for row in tournament])

