def factorial_mod(n):
    mod = 1000000007
    f = [1] * (n+1)
    for i in range(2, n+1):
        f[i] = (i * f[i-1]) % mod
    return f[n]

def count_sequences(n, m, x):
    cache = {}
    def recur(l1, r1, l2, r2):
        nonlocal cache
        if (l1, l2, r1, r2) in cache:
            return cache[(l1, l2, r1, r2)]

        total = 0
        if l1 == x:
            total = 1
            for _ in range(r1):
                total *= n - _

        for _ in range(m - r2 + 1):
            for j in range(_):
                count = recur(l1, r1, j + 1, r2 - (j + 1))
                total += count

            if l2 + _ <= m:
                total *= factorial_mod(n - _)
                total %= mod

        cache[(l1, l2, r1, r2)] = total
        return total

    return recur(x, n, 0, m)

