import sys

def max_div_tie(n, m, A):
    # Calculate the sum of A values for each contestant and each event
    sums = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            sums[i][j] = sum(A[i][j*2:2*j+2])

    # Sort the contestants by the sum of scores they receive for the best event
    sorted_indices = sorted(range(m), key=lambda i: sums[i], reverse=True)

    # Pair the best events of each contestant and calculate the sum of differences for each pair
    max_diff = 0
    for i in range(len(sorted_indices)):
        for j in range(i+1, min(i+3, m*2, n)):
            if sorted_indices[i] == sorted_indices[j]:
                max_diff = max(max_diff, abs(sums[sorted_indices[i]][j//2] - sums[sorted_indices[i]][(j-1)//2]))

    return max_diff

