# Union-Find class with logarithmic complexity find and merge operations
class UF:
    def __init__(self, n):
        self.root = [i for i in range(n)]
        self.size = [1] * n
        self.half_size = [1] * n

    def root(self, i):
        if i != self.root[i]:
            self.root[i] = self.root[self.root[i]]
        return self.root[i]

    def merge(self, i, j):
        i, j = self.root(i), self.root(j)
        hsize = self.half_size[j]
        if hsize < self.half_size[i]:
            i, j = j, i
        self.half_size[i] = max(self.half_size[i], hsize + 1)
        self.root[j] = i

