import sys

def get_sequence_difficulty(n, initial_sequence_updates, updates):
    initial_difficulty = change_count = 0
    seen_values = set()
    sequence_map = {}

    for i, num in initial_sequence_updates:
        if num in seen_values:
            change_count += 1
        if num not in seen_values:
            seen_values.add(num)
            sequence_map[num] = i

    full_difficulty = change_count
    curr_value_positions = {v: [i] for v in seen_values}

    for i, val in updates:
        change_count += 1
        full_difficulty += change_count
        change_count = 0

        if val in curr_value_positions:
            del curr_value_positions[val]
        else:
            curr_value_positions[val] = [i]

        for val, positions in curr_value_positions.items():
            diff = 0
            for j in range(1, len(positions)):
                change_count += 1
                curr_positions = positions[:]
                curr_positions[-j] = i
                curr_positions = sorted(curr_positions)
                smallest_changes = curr_positions[0] - i
                if curr_positions[1] - curr_positions[0] > 1:
                    largest_changes = curr_positions[1] - curr_positions[0]
                else:
                    largest_changes = curr_positions[1] - curr_positions[1]

                overall_diff = max((curr_positions[m] - curr_positions[m - 1]) for m in range(1, len(curr_positions)))
                diff += (smallest_changes + largest_changes) * overall_diff

            if len(curr_positions) > 1:
                overall_diff = curr_positions[0] - curr_positions[1]
                diff += overall_diff * (curr_positions[0] - i + curr_positions[1] - i)

            full_difficulty += smallest_changes + largest_changes + diff

    return full_difficulty

