from collections import Counter

def can_form_tournament(a):
    counts = Counter(a)
    maximum = max(counts.values())
    if len(a) != maximum:
        return False
    degree = [0] * len(a)
    for i, count in counts.items():
        degree[i] = count - 1
    for num, count in counts.items():
        for i in range(num):
            degree[num - 1] += 1
    return all(degree[x] >= degree[x + 1] for x in range(len(a) - 1))

def tournament_from_scores(scores):
    small = a = set(sorted(scores))
    n = len(scores)
    if not small:
        return "m=n=0"

    missing = small - a
    missing = list(missing)
    # Can't form a tournament if the missing numbers aren't a subset of the scores.
    if a & missing and missing not in small:
        return "0"

    even_count = len(small) - len(missing)
    even = [n - k // 2 for k in missing]
    odd = [n - ((n + 1) // 2 - k) for k in even] if a.isdisjoint(missing) else missing
    a += odd

    col1 = [1 if k > 0 else 0 for k in a]
    col2 = [1 if k < n - 1 else 0 for k in sorted(a)]

    return '\n'.join(' '.join(str(c) for c in col2).split('1', 1))
