from math import comb

MOD = 1_000_000_009

def choose_sum(count, symbols):
    total = 0
    for comb_ in range(count + 1):
        total = (total + comb(comb_, comb_ + symbols - 1) * comb(comb_, comb_ * symbols)) % MOD
    return total

def find_matching_sequences(length, sequences):
    if length == 0:
        return 0
    elif length == 1:
        return choose_sum(length, len(sequences))
    else:
        choices = [0] * len(sequences)
        for sequence in sequences:
            prefix_bits = ''.join(seq[:length] for seq in sequences)
        return (choose_sum(length, len(sequences)) - sum(choose_sum(length - len(seq), 1) for seq in sequences) + MOD) % MOD
