def nth_hamming_number(n, m, x):
    if n == 1:
        return 1 if x == 1 else 0

    dp = [0] * (n+1)
    dp[0] = 1
    state = 1
    curr_start = 1

    for i in range(1, n+1):
        for j in range(i-1, min(i-1, m-x), -1):
            dp[i] = (dp[i-1] + dp[j]/(m-j+1)) % MOD

            if dp[i] >= MOD:
                state |= (1 << (i-1))

        if state:
            dp[i] = (dp[i-1] + dp[next(iter(state))]) % MOD

            if dp[i] >= MOD:
                state |= (1 << (i-1))

        elif not current_start: 
            next_ch_idx = state.bit_count() + 1
            dp[i] = (dp[i-1] + dp[next_ch_idx-1]) % MOD

            if dp[i] >= MOD:
                state |= (1 << (i-1))


    return dp[n]

