def count_sequences(n, m, sequences):
    dp = [0] * (n + 1)
    max_length = 0

    # Binary search to find max_length
    for seq in sequences:
        max_length = max(max_length, len(seq))

    for length in range(1, max_length + 1):
        for start_idx in range(n - length + 1):
            end_idx = start_idx + length - 1
            dp[end_idx + 1] = (dp[end_idx + 1] + dp[start_idx]) % 1000000009

            if length == 1:
                dp[start_idx + 1] = (dp[start_idx + 1] + 1) % 1000000009

            if length > 1 and finish_index(start_idx, end_idx, sequences) in sequences:
                dp[start_idx + 1] = (dp[start_idx + 1] + 1) % 1000000009

    return dp[-1]

def finish_index(start, end, sequences):
    for seq in sequences:
        if start in range(len(seq)) and end in range(len(seq)):
            idx = 0
            while idx < len(seq):
                if seq[idx] != sequences[0][idx % len(sequences[0])]:
                    return idx
                idx += 1
    return len(seq)

