        max_t = sum(a[:n+1]) + 1
        b = deque(dx[:n+1])
        for _ in range(max_t):
            p = b.popleft()
            if p >= y:
                break
            n -= 1
            dx.append(b.popleft())

        if p < a[n + 1]:
