def hybridArrays(n, b):
    arr = [-1] * n
    i, j, cnt = 0, 0, 0
    prefixSums = []
    subsets = 0
    while i < n:
        while j < n and b[i] == b[j]:
            j += 1
        k = i + 1
        while intSubseq(b[k:n], b[i:j]):
            subsets = (subsets + pow(2, cnt - len(prefixSums), mod)) % mod
            j += 1
        arr[i] = j - i
        if k < n:
            subsets = (subsets - pow(2, cnt - 1 + arr[i], mod)) % mod
        if j - i >= arr[i]:
            prefixSums.append(j - i - 1)
            cnt += 1
        i, j = k, j
    return subsets

def intSubseq(arr1, arr2):
    arr1.sort()
    i, j = 0, 0
    maxDiff = len(arr1) - len(arr2)
    while i < len(arr1) and j < len(arr2):
        if abs(arr1[i] - arr2[j]) > maxDiff:
            return False
        if arr1[i] == arr2[j]:
            i, j = i + 1, j + 1
        elif arr1[i] < arr2[j]:
            j += 1
        else:
            i += 1
    return True if j == len(arr2) else False

