    for sequence in sequences:
        prefix = ''
        suffix = ''
        for i in range(1, len(sequence) + 1):
            if i % n == 1:
                prefix += sequence[-i]
            if i % n == n - 1:
                suffix += sequence[i-2]
            if i > 1:
                divides[prefix][suffix] = divides[prefix].get(suffix, 0) + 1
    total_sequences = m

    for prefix in divides:
        for suffix in divides[prefix]:
            for i in range(n):
                if (prefix[i:] == suffix[:-i]) or (suffix[i:] == prefix[:-i]):
                    total_sequences -= divides[prefix][suffix]

    return total_sequences % mod

# Read input
n = int(input().strip())
m = int(input().strip())
sequences = [input().strip() for _ in range(m)]

# Calculate and print the result
result = count_sequences(n, m, sequences)
print(result)
