ways = pow(2, n - 1, 1000000007)

for i in range(1, m + 1):
    lcm_i = find_lcm_up_to(m)
    if i > x:
        lcm_i = lcm(lcm_i, i)
        ways = (ways * (lcm_i - i + 1)) % 1000000007

print(ways)
